// Passos 1 e 2: a função cumprimentar recebe o parâmetro nome.
function cumprimentar(nome) {
  // Passo 3: conferimos se nome é um texto (string).
  // Se não for, paramos com um erro — número não tem nome.
  if (typeof nome !== 'string') {
    throw new Error('nome precisa ser um texto');
  }

  // Passo 4: juntamos os textos com + e devolvemos com return.
  return 'Olá, ' + nome + '!';
}

// Passo 5: chamamos a função e imprimimos o resultado.
console.log(cumprimentar('Maria')); // imprime: Olá, Maria!
